using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Claims;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using RazorLight;

namespace PdfService.Controllers
{
    public enum UserRole { Viewer = 0, Editor = 1, Admin = 2 }

    public class TemplateMetadata
    {
        public string TemplateId { get; set; }
        public string DisplayName { get; set; }
        public UserRole MinimumRole { get; set; }
        public bool AllowCustomFields { get; set; }
    }

    public class PdfRequest
    {
        public string TemplateId { get; set; }
        public Dictionary<string, string> Fields { get; set; }
        public string CustomHeaderHtml { get; set; }
    }

    public static class TemplateRegistry
    {
        private static readonly List<TemplateMetadata> _templates = new()
        {
            new() { TemplateId = "invoice", DisplayName = "Invoice", MinimumRole = UserRole.Editor, AllowCustomFields = true },
            new() { TemplateId = "report", DisplayName = "Report", MinimumRole = UserRole.Viewer, AllowCustomFields = false },
            new() { TemplateId = "contract", DisplayName = "Contract", MinimumRole = UserRole.Admin, AllowCustomFields = true }
        };

        public static TemplateMetadata GetTemplate(string id) =>
            _templates.FirstOrDefault(t => t.TemplateId == id);

        public static bool IsAuthorized(UserRole userRole, TemplateMetadata template) =>
            (int)userRole >= (int)template.MinimumRole;
    }

    public interface ITemplateRenderer
    {
        string RenderToHtml(string templateId, Dictionary<string, string> fields, string headerContent);
    }

    public class SecureTemplateRenderer : ITemplateRenderer
    {
        private readonly RazorLightEngine _engine;
        private readonly Dictionary<string, string> _templateCache;

        public SecureTemplateRenderer()
        {
            _engine = new RazorLightEngineBuilder()
                .UseEmbeddedResourcesProject(typeof(SecureTemplateRenderer))
                .UseMemoryCachingProvider()
                .Build();

            _templateCache = new Dictionary<string, string>
            {
                ["invoice"] = "<html><body><h1>Invoice</h1><div>@Model.CustomerName</div><div>@Model.Amount</div><div>@Model.HeaderSection</div></body></html>",
                ["report"] = "<html><body><h1>Report</h1><div>@Model.Title</div><div>@Model.Content</div></body></html>",
                ["contract"] = "<html><body><h1>Contract</h1><div>@Model.PartyA</div><div>@Model.PartyB</div><div>@Model.HeaderSection</div></body></html>"
            };
        }

        public string RenderToHtml(string templateId, Dictionary<string, string> fields, string headerContent)
        {
            if (!_templateCache.ContainsKey(templateId))
                throw new ArgumentException("Template not found");

            var templateSource = _templateCache[templateId];
            var model = new Dictionary<string, object>(fields.Select(kv => 
                new KeyValuePair<string, object>(kv.Key, SanitizeFieldValue(kv.Value))));

            if (headerContent != null)
            {
                model["HeaderSection"] = ProcessHeaderContent(headerContent, templateId);
            }

            var result = _engine.CompileRenderStringAsync(
                $"{templateId}_{Guid.NewGuid()}", templateSource, model).Result;
            return result;
        }

        private string SanitizeFieldValue(string input)
        {
            if (string.IsNullOrEmpty(input)) return input;
            return System.Net.WebUtility.HtmlEncode(input);
        }

        private string ProcessHeaderContent(string content, string templateId)
        {
            var sanitized = RemoveDangerousTags(content);
            return System.Net.WebUtility.HtmlEncode(sanitized);
        }

        private string RemoveDangerousTags(string html)
        {
            var dangerous = new[] { "<script", "</script", "javascript:", "onerror", "onload" };
            var result = html;
            foreach (var tag in dangerous)
            {
                result = result.Replace(tag, "", StringComparison.OrdinalIgnoreCase);
            }
            return result;
        }
    }

    [ApiController]
    [Route("api/[controller]")]
    [Authorize]
    public class PdfController : ControllerBase
    {
        private readonly ITemplateRenderer _renderer;

        public PdfController(ITemplateRenderer renderer)
        {
            _renderer = renderer;
        }

        [HttpPost("generate")]
        public IActionResult GeneratePdf([FromBody] PdfRequest request)
        {
            var userRole = GetUserRole();
            var template = TemplateRegistry.GetTemplate(request.TemplateId);

            if (template == null)
                return NotFound("Template not found");

            if (!TemplateRegistry.IsAuthorized(userRole, template))
                return Forbid();

            string headerContent = null;
            if (template.AllowCustomFields && request.CustomHeaderHtml != null)
            {
                headerContent = request.CustomHeaderHtml;
            }

            var html = _renderer.RenderToHtml(request.TemplateId, request.Fields ?? new(), headerContent);
            var pdfBytes = ConvertHtmlToPdf(html);
            return File(pdfBytes, "application/pdf", "document.pdf");
        }

        private UserRole GetUserRole()
        {
            var roleClaim = User.FindFirst(ClaimTypes.Role)?.Value;
            return Enum.TryParse<UserRole>(roleClaim, out var role) ? role : UserRole.Viewer;
        }

        private byte[] ConvertHtmlToPdf(string html)
        {
            // Simulated PDF conversion using wkhtmltopdf or similar
            return System.Text.Encoding.UTF8.GetBytes(html);
        }
    }
}
